 async function loadLibraryMedia(materials,token,limit=12){
  let requested=0;
  await Promise.all(materials.flatMap(material=>(material.attachments||[]).map(async file=>{
   const cached=libraryLinks.get(file.path);
   if(cached?.expires>Date.now()){file.view_url=cached.view_url;return;}
   if(requested++>=limit)return;
   try{
    const view_url=await window.NeoCloud.libraryMediaURL(file);
    if(token!==generation)return;
    const lifetime=file.mime?.startsWith('video/')||file.mime==='application/pdf'?1500000:40000;
    libraryLinks.set(file.path,{view_url,expires:Date.now()+lifetime});
    file.view_url=view_url;
   }catch{file.view_url='';}
  })));
 }


