 function shelfRows(){const search=librarySearch.trim().toLocaleLowerCase('pt-BR');return [...(data?.materials||[])].filter(p=>(!search||(p.title+' '+p.body).toLocaleLowerCase('pt-BR').includes(search))&&(!libraryFeaturedOnly||p.featured)&&(libraryType==='all'||libraryType==='link'&&p.url||libraryType==='text'&&!p.url&&!p.attachments?.length||(p.attachments||[]).some(f=>libraryType==='pdf'?f.mime==='application/pdf':libraryType==='text'?f.mime==='text/plain':f.mime?.startsWith(libraryType+'/')))).sort((a,b)=>librarySort==='popular'&&data.can_view_counts===false?0:(librarySort==='popular'?(Number(b.view_count)||0)-(Number(a.view_count)||0):0)||(librarySort==='oldest'?new Date(a.created_at||0)-new Date(b.created_at||0):new Date(b.created_at||0)-new Date(a.created_at||0))||String(b.id).localeCompare(String(a.id)));}
 function shelfControls(){return `<div class="library-toolbar"><button class="secondary" type="button" data-community="library_filters" aria-expanded="${libraryFilterOpen}">${shelfIcon('filter')} Filtrar e organizar</button>${context.admin?'<button class="primary" type="button" data-community="add_material">＋ Adicionar material</button>':''}</div><section class="library-filter-panel" ${libraryFilterOpen?'':'hidden'} aria-label="Filtros da Biblioteca"><label>Buscar material<input type="search" data-library-search value="${e(librarySearch)}" maxlength="100" placeholder="Título ou descrição"></label><label>Organizar<select data-library-sort>${[['recent','Mais recentes'],['oldest','Mais antigos'],['popular','Mais acessados']].map(([id,label])=>`<option value="${id}" ${librarySort===id?'selected':''} ${id==='popular'&&!data.views_ready?'disabled':''}>${label}</option>`).join('')}</select></label><label>Tipo<select data-library-type>${[['all','Todos os materiais'],['pdf','PDF'],['text','Texto'],['image','Imagem'],['video','Vídeo'],['link','Links']].map(([id,label])=>`<option value="${id}" ${libraryType===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="library-download-choice"><input type="checkbox" data-library-featured ${libraryFeaturedOnly?'checked':''}> Somente destaques</label><button class="text-btn" type="button" data-community="reset_library_filters">Limpar filtros</button>${!data.views_ready?'<p class="sub">A ordenação por acessos precisa da atualização da Biblioteca no Supabase.</p>':''}</section><p class="library-shelf-status" role="status">${status?e(status):context.admin&&!data.edit_ready?'A edição completa precisa da atualização da Biblioteca no Supabase.':''}</p>`;}
 function materialCard(p){const files=p.attachments||[],description=materialDescription(p),key=JSON.stringify([p.id,p.title,p.body,p.url,p.featured,p.created_at,context.admin,data.file_controls_ready,data.edit_ready,data.views_ready,data.can_view_counts,files.map(f=>[f.path,f.name,f.mime,f.size,f.allow_download,!!f.view_url])]);return `<article class="community-post library-material ${p.id===selectedMaterialID?'library-material-selected':''}" data-material-id="${e(p.id)}" data-render-key="${e(key)}" tabindex="-1"><div class="library-material-layout">${files.length?`<div class="library-published-files">${files.map(f=>filePreview({...f,material_id:p.id,display_name:p.title})).join('')}</div>`:p.url?`<div class="library-external-media">${mediaLink(p.url)}</div>`:''}<div class="library-material-copy"><div class="library-material-meta">${p.featured?'<span class="library-featured-badge" title="Em destaque" aria-label="Em destaque">★</span>':''}${p.created_at?`<time datetime="${e(p.created_at)}">${e(new Date(p.created_at).toLocaleDateString('pt-BR'))}</time>`:''}${context.admin&&data.can_view_counts!==false&&data.views_ready?`<span data-library-views title="Aberturas por conta e dia">${Number(p.view_count||0).toLocaleString('pt-BR')} acessos</span>`:''}</div><h2>${e(p.title)}</h2>${description?`<p class="community-text library-material-description">${e(description.length>260?description.slice(0,260)+'…':description)}</p>`:''}${description&&(description.length>260||!files.length&&!p.url)?`<button class="text-btn" type="button" data-community="read_material_text" data-id="${e(p.id)}">${shelfIcon('eye')} Ler material</button>`:''}${files.length?mediaLink(p.url):''}<div class="library-material-actions">${context.admin?`<button type="button" class="icon-btn" data-community="edit_material_files" data-id="${e(p.id)}" aria-label="Editar material" title="Editar material" ${!data.edit_ready?'disabled':''}>${shelfIcon('edit')}</button><button class="icon-btn library-feature-toggle" data-community="feature_material" data-id="${e(p.id)}" aria-pressed="${p.featured===true}" aria-label="${p.featured?'Remover destaque':'Destacar na tela inicial'}" title="${p.featured?'Remover destaque':'Destacar na tela inicial'}" ${data.library_ready?'':'disabled'}>${shelfIcon('star')}</button><button class="icon-btn library-material-delete" data-community="delete_material" data-id="${e(p.id)}" aria-label="Excluir material" title="Excluir material">${shelfIcon('trash')}</button>`:''}</div></div></div></article>`;}
